INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Notfallmanagement nur für große Unternehmen relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Organisationen können betroffen sein"}, {"text": "Ja", "correct": false, "because": "Auch kleine Firmen brauchen Pläne"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Notfallmanagement?', 3, '[{"text": "Reaktion auf Sicherheitsvorfälle", "correct": true, "because": "Minimierung von Schäden"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Sicherheit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum Notfallmanagement?', 5, '[{"text": "Incident Response Plan", "correct": true, "because": "Definiert Reaktionsschritte"}, {"text": "Kommunikationsplan", "correct": true, "because": "Koordiniert Beteiligte"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Notfallmanagement minimiert Schäden. b) Es ist nur für Cyberangriffe nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für andere Vorfälle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Notfallmanagement?', 4, '[{"text": "Reaktionspläne", "correct": false, "because": "Kern des Managements"}, {"text": "Kommunikationswege", "correct": false, "because": "Koordination sicherstellen"}, {"text": "Visuelles Design", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Notfallmanagement auch Wiederherstellung umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Teil des Response Plans"}, {"text": "Nein", "correct": false, "because": "Wiederherstellung inklusive"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist typisch für Notfallmanagement?', 3, '[{"text": "Incident Response Plan", "correct": true, "because": "Strukturiert Reaktion"}, {"text": "Hohe Serverleistung", "correct": false, "because": "Irrelevant"}, {"text": "Statische IPs", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zum Notfallmanagement?', 5, '[{"text": "Erkennung", "correct": true, "because": "Identifiziert Vorfälle"}, {"text": "Wiederherstellung", "correct": true, "because": "Stellt Normalbetrieb her"}, {"text": "Datenbankdesign", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Notfallmanagement reagiert auf Vorfälle. b) Es ist nur für IT nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für physische Vorfälle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Notfallmanagement?', 4, '[{"text": "Notfallteam", "correct": false, "because": "Koordiniert Reaktion"}, {"text": "Wiederherstellungsplan", "correct": false, "because": "Sichert Betrieb"}, {"text": "Grafisches Design", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Notfallmanagement nur reaktiv?', 2, '[{"text": "Nein", "correct": true, "because": "Auch präventive Planung"}, {"text": "Ja", "correct": false, "because": "Vorbeugung inklusive"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte deckt Notfallmanagement ab?', 4, '[{"text": "Kommunikation", "correct": true, "because": "Informiert Beteiligte"}, {"text": "Analyse", "correct": true, "because": "Bewertet Vorfälle"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Notfallmanagement automatisch läuft. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Erfordert aktive Umsetzung"}, {"text": "Ja", "correct": false, "because": "Planung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Notfallmanagement?', 3, '[{"text": "Schnelle Reaktion", "correct": true, "because": "Minimiert Schäden"}, {"text": "Schnelle Übertragung", "correct": false, "because": "Sekundär"}, {"text": "Schriftarten", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Incident Response Plan ist essenziell. b) Notfallmanagement ist nur für Cyberangriffe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch andere Notfälle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen unterstützt Notfallmanagement?', 5, '[{"text": "Erkennungssysteme", "correct": true, "because": "Identifiziert Vorfälle"}, {"text": "Backup-Wiederherstellung", "correct": true, "because": "Stellt Daten her"}, {"text": "Maximale Speicherung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Datenbankdesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Notfallmanagement unwichtig?', 3, '[{"text": "Kommunikationsplan", "correct": false, "because": "Koordination sicherstellen"}, {"text": "Reaktionsstrategie", "correct": false, "because": "Kern des Plans"}, {"text": "Animationseffekte", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Notfallmanagement nur für IT-Vorfälle?', 3, '[{"text": "Nein", "correct": true, "because": "Auch physische Notfälle"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Notfallmanagement regelmäßig getestet werden sollte?', 2, '[{"text": "Ja", "correct": true, "because": "Effektivität sicherstellen"}, {"text": "Nein", "correct": false, "because": "Tests sind nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für Notfallmanagement?', 4, '[{"text": "Incident Response Plan", "correct": true, "because": "Strukturiert Reaktion"}, {"text": "Zufällige Daten", "correct": false, "because": "Irrelevant"}, {"text": "Grafisches Design", "correct": false, "because": "Kein Schutzfokus"}]');
